INSERT INTO public.old_services (id, title, slug, content, image, is_published, order_index, created_at, updated_at, deleted_at, meta_title, meta_description) VALUES ('e5990a10-c106-4be8-948a-4a57ae6e553a', 'Bảo trì máy lạnh chuyên nghiệp', 'bao-tri-may-lanh-chuyen-nghiep', '{"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"text": "Bảo trì máy lạnh chuyên nghiệp", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Bạn đang lo lắng vì máy lạnh kém lạnh, có mùi hôi hay hóa đơn tiền điện tăng vọt? ", "type": "text"}, {"text": "Điện máy ELC", "type": "text", "marks": [{"type": "bold"}]}, {"text": " mang đến giải pháp bảo trì toàn diện: ", "type": "text"}, {"text": "Sạch khuẩn – Tiết kiệm điện – Tối ưu hiệu suất.", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "Thời điểm vàng để bảo trì máy lạnh", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "Đừng đợi đến khi máy hỏng. Việc bảo trì định kỳ giúp kéo dài tuổi thọ máy:", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Hộ gia đình:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " 6 tháng/lần (Sử dụng ít) hoặc 3 - 4 tháng/lần (Sử dụng thường xuyên).", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Văn phòng, Công ty:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " 3 tháng/lần.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Nhà máy, Xí nghiệp, Khu vực bụi bẩn:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " 1 - 2 tháng/lần.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Máy lạnh Inverter:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Đặc biệt cần vệ sinh lưới lọc và dàn nóng mỗi 6 tháng để bảo vệ các vi mạch nhạy cảm.", "type": "text"}]}]}]}, {"type": "paragraph", "content": [{"text": "Quy trình kỹ thuật 5 bước chuyên sâu", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "Tại ELC, chúng tôi không chỉ xịt rửa máy, chúng tôi bảo dưỡng toàn diện:", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Kiểm tra & An toàn:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Ngắt nguồn điện, kiểm tra tình trạng vận hành tổng quát của máy.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Đo đạc kỹ thuật:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Kiểm tra áp suất Gas và rà soát rò rỉ tại các đầu tán, đường ống dẫn.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Bảo trì hệ thống:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Kiểm tra motor quạt, máy bơm áp lực và các linh kiện cơ khí bên trong.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Vệ sinh chuyên dụng:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Dùng bơm áp lực cao và dung dịch diệt khuẩn làm sạch dàn lạnh, dàn nóng, máng nước và lưới lọc.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Vận hành & Nghiệm thu:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Lắp đặt lại thiết bị, chạy thử máy và kiểm tra dòng điện (Ampe) trước khi bàn giao.", "type": "text"}]}]}]}, {"type": "image", "attrs": {"alt": null, "src": "https://gdzihzsjfczuggwpykjk.supabase.co/storage/v1/object/public/images/services/1779793074596-vi1gn1v51ar.webp", "align": "center", "ratio": "auto", "title": null, "width": null, "height": null}}, {"type": "image", "attrs": {"alt": null, "src": "https://gdzihzsjfczuggwpykjk.supabase.co/storage/v1/object/public/images/services/1779793149806-t5hpvmzgqgb.webp", "align": "center", "ratio": "auto", "title": null, "width": null, "height": null}}, {"type": "image", "attrs": {"alt": null, "src": "https://gdzihzsjfczuggwpykjk.supabase.co/storage/v1/object/public/images/services/1779793173380-3m8675c35d8.webp", "align": "center", "ratio": "auto", "title": null, "width": null, "height": null}}, {"type": "paragraph", "content": [{"text": "Bảng giá dịch vụ niêm yết 2026", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "Cam kết minh bạch – Không phát sinh chi phí ảo", "type": "text", "marks": [{"type": "italic"}]}]}, {"type": "paragraph", "content": [{"text": "Khác biệt khi chọn Điện máy ELC", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Chuyên môn hóa:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Xử lý thuần thục các dòng máy Daikin, LG, Panasonic, Samsung, Toshiba, Electrolux...", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Tốc độ:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Có mặt trong vòng 30-60 phút sau khi tiếp nhận yêu cầu (Hỗ trợ 24/7).", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Trách nhiệm:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Kỹ thuật viên tay nghề cao, tác phong lịch sự, vệ sinh sạch sẽ khu vực làm việc.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Uy tín:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Báo giá trước khi làm, chế độ bảo hành sau bảo trì nghiêm túc.", "type": "text"}]}]}]}, {"type": "paragraph"}]}', 'https://gdzihzsjfczuggwpykjk.supabase.co/storage/v1/object/public/images/services/1779792914473-tnt5zfxod3s.webp', true, 0, '2026-04-21 13:08:57.100266+00', '2026-05-26 10:59:44.473991+00', NULL, '', '');
INSERT INTO public.old_services (id, title, slug, content, image, is_published, order_index, created_at, updated_at, deleted_at, meta_title, meta_description) VALUES ('5e169b1a-e081-4dee-b154-0f5e64e25e50', 'Thi công hệ thống điều hoà trung tâm VRV/VRF chuyên nghiệp', 'thi-cong-he-thong-dieu-hoa-trung-tam-vrvvrf-chuyen-nghiep', '{"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"text": "Thi công hệ thống điều hoà trung tâm VRV/VRF chuyên nghiệp", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Hệ thống điều hòa trung tâm ", "type": "text"}, {"text": "VRV (Variable Refrigerant Volume)", "type": "text", "marks": [{"type": "bold"}]}, {"text": " là giải pháp làm mát tối ưu nhất hiện nay dành cho các công trình quy mô lớn như biệt thự cao cấp, tòa nhà văn phòng, khách sạn và trung tâm thương mại. Tại ", "type": "text"}, {"text": "Điện máy ELC", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", chúng tôi mang đến dịch vụ tư vấn, thiết kế và thi công hệ thống VRV với tiêu chuẩn kỹ thuật quốc tế, đảm bảo sự sang trọng và bền bỉ tuyệt đối.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Hệ thống điều hòa trung tâm VRV là gì?", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "VRV là hệ thống điều hòa trung tâm sử dụng công nghệ biến tần (Inverter) để điều chỉnh lưu lượng môi chất lạnh theo phụ tải thực tế. Với khả năng kết nối một dàn nóng công suất lớn cho nhiều dàn lạnh đa dạng, VRV giải phóng không gian ngoại thất và tối ưu hóa hiệu suất làm mát nội thất.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Các dòng dàn lạnh VRV phổ biến tại ELC:", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "VRV Cassette âm trần:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Phù hợp không gian rộng, yêu cầu sự hiện đại.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "VRV Giấu trần nối ống gió:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Đỉnh cao của thẩm mỹ, cho phép tùy biến cửa gió Linear/Slot theo kiến trúc nội thất.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "VRV Đặt sàn:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Phù hợp cho các không gian sảnh lớn, nhà hàng.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "VRV Treo tường:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Giải pháp linh hoạt, tiết kiệm chi phí lắp đặt.", "type": "text"}]}]}]}, {"type": "paragraph", "content": [{"text": "Ưu điểm vượt trội của hệ thống VRV", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Tối ưu hóa năng lượng:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Công nghệ biến tần thông minh giúp tiết kiệm tới 40% điện năng so với các dòng máy truyền thống.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Vận hành thông minh:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Hệ thống cho phép điều khiển nhiệt độ độc lập tại từng khu vực, đảm bảo sự thoải mái cá nhân hóa.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Thẩm mỹ kiến trúc:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Dàn nóng tập trung giúp giữ nguyên vẻ đẹp mặt tiền tòa nhà; hệ thống ống đồng nhỏ gọn tiết kiệm không gian trần.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Độ bền cực cao:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Khả năng vận hành bền bỉ, tuổi thọ hệ thống lên đến 15-20 năm.", "type": "text"}]}]}]}, {"type": "image", "attrs": {"alt": null, "src": "https://gdzihzsjfczuggwpykjk.supabase.co/storage/v1/object/public/images/services/1779793340777-o1tpf1y229f.webp", "align": "center", "ratio": "auto", "title": null, "width": null, "height": null}}, {"type": "image", "attrs": {"alt": null, "src": "https://gdzihzsjfczuggwpykjk.supabase.co/storage/v1/object/public/images/services/1779793367312-34p50a7xm0v.webp", "align": "center", "ratio": "auto", "title": null, "width": null, "height": null}}, {"type": "paragraph", "content": [{"text": "Quy trình lắp đặt tiêu chuẩn 12 bước chuyên sâu tại ELC", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "Để hệ thống VRV vận hành hoàn hảo, đội ngũ kỹ sư ELC tuân thủ nghiêm ngặt quy trình kỹ thuật sau:", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Lắp đặt ống chờ qua tường:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Xác định chính xác vị trí xuyên tường, đảm bảo chống thấm kỹ thuật.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Lắp đặt dàn lạnh:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Treo dàn lạnh bằng ty ren cường độ cao, đảm bảo độ cân bằng tuyệt đối để tránh đọng nước.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Lắp đặt hệ thống giá đỡ & Ty treo:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Cố định hệ thống giá đỡ ống đồng, ống nước thải theo lộ trình bản vẽ.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Thi công đường ống Gas (Ống đồng):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Sử dụng kỹ thuật ", "type": "text"}, {"text": "hàn Nitơ", "type": "text", "marks": [{"type": "bold"}]}, {"text": " để làm sạch lòng ống, tránh muội than gây tắc nghẽn van tiết lưu.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Lắp đặt hệ thống thoát nước ngưng:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Đảm bảo độ dốc tối thiểu 1% và có bẫy nước (U-trap) ngăn mùi.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Lắp đặt ống gió dẫn lạnh:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Kết nối ống gió mềm/cứng và các hộp box cửa gió (đối với dòng giấu trần).", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Bọc bảo ôn toàn diện:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Sử dụng vật liệu cách nhiệt chuyên dụng tại các điểm nối để ngăn ngừa hiện tượng \"đổ mồ hôi\" ống.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Hệ thống điện điều khiển & Tín hiệu:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Kết nối dây tín hiệu tiêu chuẩn, đảm bảo giao tiếp thông suốt giữa dàn nóng và dàn lạnh.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Lắp đặt dàn nóng:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Đặt tại vị trí thông thoáng, có bệ đỡ chống rung và khoảng cách giải nhiệt đúng tiêu chuẩn.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Thử áp lực hệ thống:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Nén Nitơ cao áp để kiểm tra rò rỉ toàn bộ hệ thống trong 24 giờ.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Hút chân không sâu:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Loại bỏ hoàn toàn không khí và hơi ẩm bên trong đường ống bằng máy hút chuyên dụng.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Nạp Gas bổ sung & Vận hành:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Tính toán lượng gas bổ sung theo chiều dài thực tế đường ống, chạy thử nghiệm và hiệu chỉnh thông số.", "type": "text"}]}]}]}, {"type": "image", "attrs": {"alt": null, "src": "https://gdzihzsjfczuggwpykjk.supabase.co/storage/v1/object/public/images/services/1779793414709-cnbacrn4vho.webp", "align": "center", "ratio": "auto", "title": null, "width": null, "height": null}}, {"type": "image", "attrs": {"alt": null, "src": "https://gdzihzsjfczuggwpykjk.supabase.co/storage/v1/object/public/images/services/1779793431052-6qia3gdmaft.webp", "align": "center", "ratio": "auto", "title": null, "width": null, "height": null}}, {"type": "paragraph", "content": [{"text": "Tại sao doanh nghiệp và chủ biệt thự chọn Điện máy ELC?", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Năng lực kỹ sư:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Đội ngũ chuyên gia HVAC giàu kinh nghiệm, am hiểu sâu sắc các hệ thống VRV của Daikin, Mitsubishi, LG, Panasonic...", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Công nghệ hiện đại:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Ứng dụng các thiết bị đo đạc, máy hàn và công cụ thi công tiên tiến nhất.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Tích hợp giải pháp:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Khả năng tích hợp hệ thống điều hòa với Nhà thông minh (Smart Home) và Hệ thống lọc khí tươi chuyên sâu.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Hậu mãi tận tâm:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Chính sách bảo trì định kỳ 3-6 tháng giúp hệ thống luôn vận hành ở trạng thái tốt nhất.", "type": "text"}]}]}]}, {"type": "paragraph"}]}', 'https://gdzihzsjfczuggwpykjk.supabase.co/storage/v1/object/public/images/services/1779793298040-ql457o0sx2i.webp', true, 0, '2026-04-21 13:14:35.815966+00', '2026-05-26 11:03:54.90225+00', NULL, '', '');
INSERT INTO public.old_services (id, title, slug, content, image, is_published, order_index, created_at, updated_at, deleted_at, meta_title, meta_description) VALUES ('20c51df4-ad88-473a-9499-4943cb69bde9', 'Thu mua máy lạnh cũ giá cao', 'thu-mua-may-lanh-cu-gia-cao', '{"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"text": "Thu mua máy lạnh cũ giá cao", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Thanh lý nhanh – Định giá minh bạch – Thu hồi giá trị tối đa", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "ạn đang sở hữu hệ thống máy lạnh đã qua sử dụng, thiết bị lỗi thời hoặc cần thanh lý số lượng lớn để nâng cấp công nghệ làm mát? ", "type": "text"}, {"text": "Điện máy ELC", "type": "text", "marks": [{"type": "bold"}]}, {"text": " mang đến giải pháp thu mua chuyên nghiệp, giúp khách hàng thu hồi ngân sách tối đa với quy trình vận hành tinh gọn.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Tại sao đối tác tin chọn Điện máy ELC?", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Định giá dựa trên giá trị thực:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Chúng tôi không chỉ mua \"xác máy\", ELC định giá dựa trên Model, hiệu suất vận hành và khả năng tái sử dụng. Mức thu mua có thể đạt từ ", "type": "text"}, {"text": "50% – 70%", "type": "text", "marks": [{"type": "bold"}]}, {"text": " giá trị gốc.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Minh bạch kỹ thuật:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Tuyệt đối không có tình trạng ép giá. Kỹ thuật viên HVAC sẽ giám định trực tiếp và cung cấp bảng báo giá chi tiết để khách hàng phê duyệt.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Tháo dỡ chuẩn Kỹ thuật:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Thao tác tháo dỡ được thực hiện bởi đội ngũ kỹ sư chuyên nghiệp, đảm bảo an toàn tuyệt đối cho hệ thống điện và không ảnh hưởng đến kết cấu thẩm mỹ của công trình.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Thanh toán dứt điểm:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Quyết toán tiền mặt hoặc chuyển khoản ngay sau khi thống nhất giá, hỗ trợ giải phóng mặt bằng trong ngày.", "type": "text"}]}]}]}, {"type": "paragraph"}, {"type": "image", "attrs": {"alt": null, "src": "https://gdzihzsjfczuggwpykjk.supabase.co/storage/v1/object/public/images/services/1780131347670-x74o08if0l7.webp", "align": "center", "ratio": "auto", "title": null, "width": null, "height": null}}, {"type": "image", "attrs": {"alt": null, "src": "https://gdzihzsjfczuggwpykjk.supabase.co/storage/v1/object/public/images/services/1780131348172-suyuoh95kgj.webp", "align": "center", "ratio": "auto", "title": null, "width": null, "height": null}}, {"type": "image", "attrs": {"alt": null, "src": "https://gdzihzsjfczuggwpykjk.supabase.co/storage/v1/object/public/images/services/1780131348738-oc42n8junt.webp", "align": "center", "ratio": "auto", "title": null, "width": null, "height": null}}, {"type": "image", "attrs": {"alt": null, "src": "https://gdzihzsjfczuggwpykjk.supabase.co/storage/v1/object/public/images/services/1780131347121-2lq45nq7fa3.webp", "align": "center", "ratio": "auto", "title": null, "width": null, "height": null}}, {"type": "paragraph", "content": [{"text": "Danh mục thiết bị thu mua", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "ELC tiếp nhận thanh lý đa dạng các dòng máy với mọi công suất:", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Hệ thống dân dụng:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Các dòng máy treo tường từ ", "type": "text"}, {"text": "1.0 HP – 2.5 HP", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (Daikin, Panasonic, LG, Samsung, Mitsubishi...).", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Hệ thống thương mại:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Máy lạnh âm trần Cassette, máy lạnh giấu trần nối ống gió, máy lạnh tủ đứng.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Hệ thống dự án – Công nghiệp:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Thu mua trọn gói hệ thống điều hòa trung tâm ", "type": "text"}, {"text": "VRV, VRF, Multi, Chiller", "type": "text", "marks": [{"type": "bold"}]}, {"text": " tại các tòa nhà cao tầng, khách sạn, resort và nhà xưởng quy mô lớn.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Quy mô:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Đáp ứng mọi nhu cầu từ đơn lẻ (01 bộ) đến dự án số lượng hàng trăm bộ.", "type": "text"}]}]}]}, {"type": "paragraph"}, {"type": "image", "attrs": {"alt": null, "src": "https://gdzihzsjfczuggwpykjk.supabase.co/storage/v1/object/public/images/services/1780131386712-vrnt00q3b0g.webp", "align": "center", "ratio": "auto", "title": null, "width": null, "height": null}}, {"type": "image", "attrs": {"alt": null, "src": "https://gdzihzsjfczuggwpykjk.supabase.co/storage/v1/object/public/images/services/1780131387169-f2ymxequs6t.webp", "align": "center", "ratio": "auto", "title": null, "width": null, "height": null}}, {"type": "image", "attrs": {"alt": null, "src": "https://gdzihzsjfczuggwpykjk.supabase.co/storage/v1/object/public/images/services/1780131387624-8kwbtcuxqoe.webp", "align": "center", "ratio": "auto", "title": null, "width": null, "height": null}}, {"type": "image", "attrs": {"alt": null, "src": "https://gdzihzsjfczuggwpykjk.supabase.co/storage/v1/object/public/images/services/1780131388125-ca8jj8e009n.webp", "align": "center", "ratio": "auto", "title": null, "width": null, "height": null}}, {"type": "image", "attrs": {"alt": null, "src": "https://gdzihzsjfczuggwpykjk.supabase.co/storage/v1/object/public/images/services/1780131385923-64kv59gt0jx.webp", "align": "center", "ratio": "auto", "title": null, "width": null, "height": null}}, {"type": "paragraph", "content": [{"text": "Quy trình thu mua tinh gọn (4 Bước)", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Tiếp nhận dữ liệu:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Khách hàng gửi thông tin/hình ảnh qua Hotline/Zalo để nhận báo giá sơ bộ trong 10 phút.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Khảo sát hiện trường:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Chuyên viên kỹ thuật có mặt tại địa điểm để giám định thực tế.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Thống nhất định giá:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Chốt mức giá thu mua cuối cùng dựa trên các tiêu chuẩn kỹ thuật chuyên sâu.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Giải phóng mặt bằng:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Thực hiện tháo dỡ, dọn dẹp hiện trường sạch sẽ và thanh toán trọn gói.", "type": "text"}]}]}]}, {"type": "paragraph", "content": [{"text": "Chương trình đặc biệt: “Nâng cấp công nghệ – Đổi cũ lấy mới”", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "Nhằm hỗ trợ khách hàng chuyển đổi sang các dòng máy Inverter thế hệ mới, ELC triển khai gói ưu đãi:", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Hỗ trợ giá Trade-in:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Thu mua máy cũ cao hơn giá thị trường khi nâng cấp máy mới tại ELC.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Ưu đãi thi công:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Tặng gói nhân công lắp đặt và vật tư phụ cho các đơn hàng đổi mới.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Tối ưu năng lượng:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Tư vấn giải pháp giúp giảm thiểu lên đến ", "type": "text"}, {"text": "30 – 40%", "type": "text", "marks": [{"type": "bold"}]}, {"text": " chi phí điện năng hàng tháng.", "type": "text"}]}]}]}, {"type": "paragraph", "content": [{"text": "Chính sách dành cho Đối tác & Dự án", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Đấu thầu thanh lý:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Nhận tháo dỡ trọn gói hệ thống HVAC tại các tòa nhà văn phòng, dự án cải tạo.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Cam kết tiến độ:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Đảm bảo thời gian giải phóng mặt bằng đúng cam kết để chủ đầu tư triển khai hạng mục mới.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Chiết khấu kết nối:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Chính sách hoa hồng hấp dẫn cho đối tác giới thiệu các dự án thanh lý quy mô lớn.", "type": "text"}]}]}]}, {"type": "paragraph"}]}', 'https://gdzihzsjfczuggwpykjk.supabase.co/storage/v1/object/public/images/services/1780131297545-pb8hgh134bb.webp', true, 0, '2026-04-21 13:06:32.75405+00', '2026-05-30 08:56:34.074309+00', NULL, '', '');
INSERT INTO public.old_services (id, title, slug, content, image, is_published, order_index, created_at, updated_at, deleted_at, meta_title, meta_description) VALUES ('1f5a2c3a-83d7-41a5-8fd5-4254643cb6ff', 'Tư vấn thiết kế hệ thống HVAC chuyên sâu', 'tu-van-thiet-ke-he-thong-hvac-chuyen-sau', '{"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"text": "Tư vấn thiết kế hệ thống HVAC chuyên sâu", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Giải pháp Kỹ thuật tối ưu – Đồng bộ Kiến trúc – Nâng tầm Chất lượng không khí", "type": "text", "marks": [{"type": "bold"}, {"type": "italic"}]}]}, {"type": "paragraph", "content": [{"text": "Tại ", "type": "text"}, {"text": "Điện máy ELC", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", chúng tôi không chỉ cung cấp thiết bị mà mang đến giải pháp ", "type": "text"}, {"text": "HVAC (Sưởi ấm - Thông gió - Điều hòa không khí)", "type": "text", "marks": [{"type": "bold"}]}, {"text": " tổng thể. Với đội ngũ kỹ sư chuyên môn cao, ELC cam kết kiến tạo những hệ thống vận hành thông minh, giúp khách hàng tối ưu công suất, tiết kiệm điện năng và bảo vệ sức khỏe toàn diện.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Dịch vụ Tư vấn & Thiết kế giải pháp hiện đại", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "Chúng tôi tập trung vào sự giao thoa giữa ", "type": "text"}, {"text": "Hiệu suất – Thẩm mỹ – Sức khỏe", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", ứng dụng những công nghệ tiên tiến nhất hiện nay:", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Hệ thống Điều hòa trung tâm (VRV/VRF):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Giải pháp quản lý nhiệt độ đa điểm cho biệt thự, Penthouse và văn phòng cao cấp. Khả năng điều khiển linh hoạt giúp tối ưu hóa chi phí vận hành.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Hệ thống Giấu trần nối ống gió:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Sự lựa chọn hàng đầu cho không gian nội thất thượng lưu. Chúng tôi thiết kế các miệng gió ", "type": "text"}, {"text": "Linear, Slot", "type": "text", "marks": [{"type": "bold"}]}, {"text": " tinh gọn, đảm bảo hệ thống \"ẩn mình\" hoàn hảo trong kiến trúc.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Giải pháp Cấp khí tươi (Fresh Air):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Ứng dụng công nghệ xử lý không khí tiêu chuẩn (như ", "type": "text"}, {"text": "Menred P5", "type": "text", "marks": [{"type": "bold"}]}, {"text": ") để kiểm soát nồng độ $CO_2$, cung cấp lượng Oxy tươi mới cho không gian kín, loại bỏ cảm giác ngột ngạt.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Công nghệ Lọc khí & Khử khuẩn:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Tích hợp màng lọc ", "type": "text"}, {"text": "HEPA", "type": "text", "marks": [{"type": "bold"}]}, {"text": " và công nghệ ", "type": "text"}, {"text": "Plasma", "type": "text", "marks": [{"type": "bold"}]}, {"text": " hiện đại, giúp loại bỏ bụi mịn ", "type": "text"}, {"text": "PM2.5", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", vi khuẩn và các tác nhân gây dị ứng, tạo ra môi trường sống an toàn tuyệt đối.", "type": "text"}]}]}]}, {"type": "paragraph"}, {"type": "image", "attrs": {"alt": null, "src": "https://gdzihzsjfczuggwpykjk.supabase.co/storage/v1/object/public/images/services/1780131673235-cgnhbamemvd.webp", "align": "center", "ratio": "auto", "title": null, "width": null, "height": null}}, {"type": "image", "attrs": {"alt": null, "src": "https://gdzihzsjfczuggwpykjk.supabase.co/storage/v1/object/public/images/services/1780131672773-0rcourlexfy.webp", "align": "center", "ratio": "auto", "title": null, "wid